//! Shared helpers for integration tests.

use std::path::PathBuf;

/// Golden fixtures: the canonical `protocol/fixtures/` generated by the Swift
/// implementation when present in the repository, otherwise this crate's own
/// samples in `tests/fixtures/`. Set `PLANMETER_FIXTURES` to force a directory.
pub fn fixtures_dir() -> PathBuf {
    if let Some(dir) = std::env::var_os("PLANMETER_FIXTURES") {
        return PathBuf::from(dir);
    }
    let manifest = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let canonical = manifest.join("../protocol/fixtures");
    if canonical.join("replies").is_dir() || canonical.join("control").is_dir() {
        return canonical;
    }
    manifest.join("tests/fixtures")
}

/// JSON files in a fixture subdirectory, sorted by name.
pub fn json_files(sub: &str) -> Vec<PathBuf> {
    let dir = fixtures_dir().join(sub);
    let mut files: Vec<PathBuf> = std::fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", dir.display()))
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.extension().is_some_and(|x| x == "json"))
        .collect();
    files.sort();
    files
}

pub fn stem(path: &std::path::Path) -> String {
    path.file_stem()
        .unwrap_or_default()
        .to_string_lossy()
        .into_owned()
}
